// The meadow's background: sky, hills, field and the winding path.
//
// Unlike the small sprites this is generated by code, because 320 x 180 pixels
// is too big to type by hand. The idea is simple: paint every pixel of a grid
// (later layers cover earlier ones), then squash the grid into as few
// rectangles as possible. The result is an ordinary Sprite, drawn by the same
// PixelSprite component as everything else.
//
// Everything here is deterministic. A seeded random-number generator places the
// grass tufts and flowers, so the picture is identical on every visit and in
// every test.
import type { Run, Sprite } from '../sprite';
import type { SceneColor } from '../themes';

// The scene is drawn on a 320 x 180 pixel canvas (16:9). Other art in the
// scene is positioned in these same coordinates (see meadowLayout.ts).
export const SCENE_WIDTH = 320;
export const SCENE_HEIGHT = 180;

const GROUND_TOP = 110; // where the grass field begins
const DOOR_X = 218; // the path starts at the cabin door
const PATH_TOP = 114;

// Sky colour bands, top to bottom: [first row of the NEXT band, colour].
const SKY_BANDS: readonly (readonly [number, SceneColor])[] = [
  [36, 'skyTop'],
  [68, 'skyMid'],
  [SCENE_HEIGHT, 'skyLow'],
];

// mulberry32: a tiny seeded random-number generator. Same seed, same numbers.
function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// The path is narrow at the door and widens toward the viewer (perspective),
// bending in an S. Returns the left and right edge of the path on row y, or
// null above the door.
function pathAt(y: number): { left: number; right: number } | null {
  if (y < PATH_TOP) return null;
  const t = (y - PATH_TOP) / (SCENE_HEIGHT - 1 - PATH_TOP); // 0 at door .. 1 at bottom
  const center = DOOR_X - 68 * t + 10 * Math.sin(t * Math.PI * 2);
  const half = 4 + 22 * Math.pow(t, 1.2);
  return { left: Math.round(center - half), right: Math.round(center + half) };
}

function nearPath(x: number, y: number, margin: number): boolean {
  const p = pathAt(y);
  return p !== null && x >= p.left - margin && x <= p.right + margin;
}

function skyColor(x: number, y: number): SceneColor {
  const index = SKY_BANDS.findIndex(([until]) => y < until);
  const [until, color] = SKY_BANDS[index]!;
  const next = SKY_BANDS[index + 1];
  // Dither: in the last two rows of a band, the next band's colour shows
  // through in alternating 4-pixel blocks. This softens the hard edge between
  // bands. Blocks, not single pixels, because each single pixel would become
  // its own rectangle and triple the size of the picture.
  if (next && y >= until - 2 && (Math.floor(x / 4) + y) % 2 === 0) return next[1];
  return color;
}

// Turns a full grid of colours into rectangles. First each row is split into
// horizontal runs of one colour; then a run that is identical to the one
// directly above it (same colour, start and width) is merged into it by making
// the rectangle taller.
function encode(grid: readonly SceneColor[]): Run[] {
  const runs: Run[] = [];
  let open = new Map<string, Run>();

  for (let y = 0; y < SCENE_HEIGHT; y++) {
    const nextOpen = new Map<string, Run>();
    let x = 0;
    while (x < SCENE_WIDTH) {
      const color = grid[y * SCENE_WIDTH + x]!;
      let end = x + 1;
      while (end < SCENE_WIDTH && grid[y * SCENE_WIDTH + end] === color) end++;

      const key = `${color}:${x}:${end - x}`;
      const above = open.get(key);
      if (above) {
        above.height += 1;
        nextOpen.set(key, above);
      } else {
        const run: Run = { color, x, y, width: end - x, height: 1 };
        runs.push(run);
        nextOpen.set(key, run);
      }
      x = end;
    }
    open = nextOpen;
  }
  return runs;
}

export function createMeadowBackdrop(): Sprite {
  const grid: SceneColor[] = new Array<SceneColor>(SCENE_WIDTH * SCENE_HEIGHT);
  const paint = (x: number, y: number, color: SceneColor) => {
    if (x >= 0 && x < SCENE_WIDTH && y >= 0 && y < SCENE_HEIGHT) {
      grid[y * SCENE_WIDTH + x] = color;
    }
  };
  const random = seededRandom(20240607);

  // Layer 1: sky.
  for (let y = 0; y < SCENE_HEIGHT; y++) {
    for (let x = 0; x < SCENE_WIDTH; x++) paint(x, y, skyColor(x, y));
  }

  // Layers 2 and 3: two rows of hills, far then near. For each column the
  // hill's top is a sum of two sine waves (rounded to whole pixels, so the edge
  // is stepped like pixel art); everything from there down is hill colour.
  for (let x = 0; x < SCENE_WIDTH; x++) {
    const farTop = 86 + Math.round(5 * Math.sin(x / 41 + 0.5) + 3 * Math.sin(x / 17 + 2));
    for (let y = farTop; y < SCENE_HEIGHT; y++) paint(x, y, 'hillFar');
    const nearTop = 98 + Math.round(6 * Math.sin(x / 58 + 2.4) + 3 * Math.sin(x / 23));
    for (let y = nearTop; y < SCENE_HEIGHT; y++) paint(x, y, 'hillNear');
  }

  // Layer 4: the grass field, with a gently wavy top edge.
  for (let x = 0; x < SCENE_WIDTH; x++) {
    const top = GROUND_TOP + Math.round(1.5 * Math.sin(x / 29));
    for (let y = top; y < SCENE_HEIGHT; y++) paint(x, y, 'grass');
  }

  // Layer 5: the path, with a two-pixel darker edge and a few pebbles.
  for (let y = PATH_TOP; y < SCENE_HEIGHT; y++) {
    const p = pathAt(y)!;
    for (let x = p.left; x <= p.right; x++) {
      const onEdge = x <= p.left + 1 || x >= p.right - 1;
      paint(x, y, onEdge ? 'pathEdge' : 'path');
    }
  }
  for (let i = 0; i < 40; i++) {
    const y = PATH_TOP + 4 + Math.floor(random() * (SCENE_HEIGHT - PATH_TOP - 6));
    const p = pathAt(y)!;
    const x = p.left + 4 + Math.floor(random() * Math.max(1, p.right - p.left - 8));
    paint(x, y, 'pathEdge');
  }

  // Layer 6: grass tufts. Each is three pixels in a small "v" shape.
  for (let i = 0; i < 220; i++) {
    const x = Math.floor(random() * (SCENE_WIDTH - 3));
    const y = GROUND_TOP + 6 + Math.floor(random() * (SCENE_HEIGHT - GROUND_TOP - 8));
    if (nearPath(x, y, 4)) continue;
    paint(x, y, 'grassDark');
    paint(x + 2, y, 'grassDark');
    paint(x + 1, y - 1, 'grassLight');
  }

  // Layer 7: tiny flowers, a coloured dot over a dark-green stem pixel.
  const petals: SceneColor[] = ['flowerPink', 'flowerYellow', 'flowerWhite'];
  for (let i = 0; i < 40; i++) {
    const x = Math.floor(random() * SCENE_WIDTH);
    const y = GROUND_TOP + 8 + Math.floor(random() * (SCENE_HEIGHT - GROUND_TOP - 12));
    if (nearPath(x, y, 6)) continue;
    paint(x, y, petals[i % petals.length]!);
    paint(x, y + 1, 'grassDark');
  }

  return { width: SCENE_WIDTH, height: SCENE_HEIGHT, runs: encode(grid) };
}

// Built once, when the module first loads.
export const meadowBackdrop: Sprite = createMeadowBackdrop();
